// Une la base de conocimiento (RAG) en un solo texto
const contexto = $input.all()
  .map(i => i.json.fields ?? i.json)
  .map(f => `${f.Tema}: ${f.Contenido}`)
  .join('\n');

// Un ítem por cada lead que pasó la validación
return $('Validar datos mínimos').all().map(lead => {
  const f = lead.json.fields;
  const servicio = f['Servicio (nombre)'];
  return {
    json: {
      lead_id: lead.json.id,
      nombre: f.Nombre,
      email: f.Email,
      cantidad_perros: Number(f['Cantidad de perros']),
      servicio: Array.isArray(servicio) ? servicio[0] : (servicio ?? 'No indicado'),
      mensaje: f.Mensaje,
      contexto
    }
  };
});

