// Lee la respuesta de la IA, esté donde esté según la versión del nodo
const j = $json;
const msg = (j.output ?? []).find(o => o.type === 'message');
let raw = j.message?.content
  ?? msg?.content?.find(c => c.type === 'output_text')?.text
  ?? j.output_text ?? j.text ?? j.content;

// Por si la IA envuelve el JSON entre ```json ... ```
if (typeof raw === 'string') raw = raw.replace(/^```(json)?|```$/g, '').trim();

let data = null;
try { data = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) {}

const valido = !!data
  && ['VIP', 'Normal'].includes(data.categoria)
  && typeof data.asunto === 'string'
  && typeof data.respuesta === 'string' && data.respuesta.trim().length > 0;

const lead = $('Armar contexto').item.json;
return {
  json: {
    valido,
    lead_id: lead.lead_id,
    nombre: lead.nombre,
    email: lead.email,
    servicio: lead.servicio,
    cantidad_perros: lead.cantidad_perros,
    categoria: data?.categoria ?? null,
    puntaje: Number(data?.puntaje) || null,
    motivo: data?.motivo ?? '',
    asunto: data?.asunto ?? '',
    respuesta: data?.respuesta ?? '',
    // datos para la ruta de error, si hace falta
    tipo: 'Respuesta IA inválida',
    nodo: 'Parsear respuesta IA',
    mensaje: valido ? '' : String(JSON.stringify(raw) ?? 'Sin contenido').slice(0, 500)
  }
};

